n=30
g=[[0]*n for _ in range(n)]
tiles=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# complete 4x4 framed tiles
for tr in range(4):
 for tc in range(4):
  rs,cs=1+7*tr,1+7*tc
  for dr in range(5):
   for dc in range(5):
    g[rs+dr][cs+dc]=tiles[tr][tc] if 1<=dr<=3 and 1<=dc<=3 else 4
# partial rightmost tile column and bottom tile row, as shown
for r in range(1,6): g[r][29]=4
for r in range(8,13): g[r][29]=4
for r in range(15,20): g[r][29]=4
for r in range(22,27): g[r][29]=4
for c in range(1,30): g[29][c]=4
# horizontal lines in the two-cell gaps, for each motif-center row
for tr, color in enumerate([3,2,3,2]):
 for rr in range(2+7*tr,5+7*tr):
  for gap in range(3):
   for cc in (6+7*gap,7+7*gap): g[rr][cc]=color
# vertical lines in separators; high color wins overlaps
vgaps=[[3,2,2,3],[3,8,8,3],[2,8,8,2]]
# actual expected middle pair: max colors all aligned overlap; apply max-based table
for gap, colors in enumerate(vgaps):
 for tc,color in enumerate(colors):
  for cc in range(2+7*tc,5+7*tc):
   for rr in (6+7*gap,7+7*gap): g[rr][cc]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

n=30
g2=[[0]*n for _ in range(n)]
cores=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for tr in range(4):
 for tc in range(4):
  rs,cs=1+7*tr,1+7*tc
  for dr in range(5):
   for dc in range(5): g2[rs+dr][cs+dc]=cores[tr][tc] if 1<=dr<=3 and 1<=dc<=3 else 4
# partial right edge at c29 for rows 1:5,8:12,15:19,22:26; and row29
for rs in (1,8,15,22):
 for dr in range(5): g2[rs+dr][29]=4
for cs in (1,8,15,22):
 for dc in range(5): g2[29][cs+dc]=4
g2[29][29]=4
# connect only non-background interior colors 3 and 8: horizontal on equal-color spans
# row groups 0 and 2: 3 from tile col0 to col3
for tr,color,cols in [(0,3,(0,3)),(2,3,(0,3)),(1,8,(1,2)),(3,8,(1,2))]:
 for rr in range(2+7*tr,5+7*tr):
  for gap in range(cols[0],cols[1]):
   for cc in (6+7*gap,7+7*gap): g2[rr][cc]=color
# vertical equal color pairs: 3 at cols0,3 row0->row2; 8 at cols1,2 row1->row3
for tc,color,rgap0,rgap1 in [(0,3,0,2),(3,3,0,2),(1,8,1,3),(2,8,1,3)]:
 for gap in range(rgap0,rgap1):
  for rr in (6+7*gap,7+7*gap):
   for cc in range(2+7*tc,5+7*tc): g2[rr][cc]=color
answer2=json.dumps({'action':'submit','grid':g2},separators=(',',':'))
